using System.IO;
using System.Text;
using RenoDXMfgUnlocker;

internal static class Mfg181CompatibilityChecks
{
    internal const string Unavailable="Generation-method editing requires addon 1.8.0 or newer with the required configuration support. Existing settings remain available.";
    internal static IEnumerable<(string Name,Action Run)> All(){
        yield return("mfg181 older 1.7 schemas do not expose generation methods",Older);
        yield return("mfg181 reviewed 180 and 181 numeric resource versions expose all three methods",Reviewed);
        yield return("mfg181 future stable versions inherit minimum capabilities and explicit exclusions override them",Future);
        yield return("mfg181 unknown malformed prerelease and embedded numeric text fail closed",Unknown);
        yield return("mfg181 all three methods roundtrip exact INI keys and restore original bytes",Roundtrip);
        yield return("mfg181 XMX still blocks NVIDIA-only direct writes and preserves independent settings",Lockout);
        yield return("mfg181 settings still reject running game stale config and invalid values",Guards);
        yield return("mfg181 Intel API gates share reviewed capabilities and preserve dependency hashes",Intel);
        yield return("mfg181 saved generation diagnostics support 181 without claiming runtime activity",Diagnostics);
        yield return("mfg181 live UI uses capability-based unavailable message in six catalogs",Messages);
    }
    private static void Check(bool value,string reason){if(!value)throw new Exception(reason);}
    private static void Reject(Action action){try{action();}catch(Exception e)when(e is InvalidDataException or InvalidOperationException or IOException){return;}throw new Exception("Unsafe operation accepted");}
    private static (string Root,string Path,MfgUnlockSettingsService Service) Fixture(){var root=Path.Combine(Path.GetTempPath(),"RenoDX-mfg181",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);return(root,Path.Combine(root,"MFGAdaUnlock.ini"),new(true));}
    private static Dictionary<string,string> Values(string mode)=>new(){{"Selected",mode=="Intel"?"XeMFG":"DLSSG"},{"XmxGenerator",mode=="XMX"?"1":"0"}};
    private static void Older(){var f=Fixture();foreach(var version in new[]{"1.7.0","1.7.0.0","1.7.1","1.7.9","1.7.99.0"}){var s=f.Service.Load(f.Path,f.Root,version);Check(!s.Settings.Any(x=>MfgSettingsLayout.IsMethodKey(x.Definition.Key)),"Old selector exposed");Check(GenerationMethodPresenter.Describe(s,new Dictionary<string,string?>()) is null,"Old presentation exposed");Reject(()=>f.Service.CreateUpdatedBytes(s,Values("XMX")));}}
    private static void Reviewed(){var f=Fixture();foreach(var version in new[]{"1.8.0","1.8.0.0","1.8.1","1.8.1.0","1.8.2","1.9.0","2.0.0","1,8,1,0"," 1.8.1.0 "}){var s=f.Service.Load(f.Path,f.Root,version);Check(s.IsSupportedAddonVersion&&s.Settings.Count==8,"Supported schema missing: "+version);foreach(var mode in new[]{"NVIDIA","Intel","XMX"}){var proposed=Values(mode).ToDictionary(x=>x.Key,x=>(string?)x.Value);var p=GenerationMethodPresenter.Describe(s,proposed);Check(p is not null&&p.SelectedXmx==(mode=="XMX"),"Method unavailable: "+mode+" / "+version);}}}
    private static void Future(){
        foreach(var version in new[]{"1.8.2","1.9.0","1.10.0","2.0.0"})Check(MfgSettingsCapabilityCatalog.SupportsGenerationMethods(version),"Newer stable release blocked");
        Check(!MfgSettingsCapabilityCatalog.SupportsGenerationMethods("1.7.9"),"Minimum version not enforced");
        // Synthetic exception rules test future removals; no production exclusion is invented.
        var rule=new MfgSettingsCapabilityCatalog.Rule(new(1,8,0,0),[new(new(2,0,0,0),new(2,1,0,0),"synthetic removal")]);
        Check(MfgSettingsCapabilityCatalog.Supports("1.10.0",rule)&&!MfgSettingsCapabilityCatalog.Supports("2.0.5",rule)&&MfgSettingsCapabilityCatalog.Supports("2.1.0",rule),"Compatibility exclusion boundaries wrong");
        var removed=rule with{Exclusions=[new(new(2,0,0,0),null,"synthetic permanent removal")]};
        Check(!MfgSettingsCapabilityCatalog.Supports("3.0.0",removed),"Open-ended removal ignored");
    }
    private static void Unknown(){var f=Fixture();foreach(var version in new[]{"","Unknown","1.8","1.5.7","1.8.1-beta.1","prefix 1.8.1.0","1.8.1.0 suffix","1.8.1.0.0","1,8.1.0","999999999999.8.1"}){Check(!f.Service.SupportsVersion(version)&&!MfgSettingsCapabilityCatalog.SupportsGenerationMethods(version),"Invalid metadata accepted: "+version);var s=f.Service.Load(f.Path,f.Root,version);Reject(()=>f.Service.CreateUpdatedBytes(s,Values("XMX")));}Check(MfgSettingsCapabilityCatalog.Find(null) is null,"Null version accepted");}
    private static void Roundtrip(){foreach(var version in new[]{"1.8.0","1.8.1.0","1.8.2","1.9.0","2.0.0"})foreach(var mode in new[]{"NVIDIA","Intel","XMX"}){var f=Fixture();var text="; keep\r\n[Backend]\r\n; backend\r\nSelected=DLSSG\r\n[DLSSG]\r\nXmxGenerator=0\r\nForceBorderless=1\r\n[XeFG]\r\nUIStabilization=1\r\n[Foreign]\r\nKeep=yes\r\n";File.WriteAllText(f.Path,text,new UTF8Encoding(true));var before=File.ReadAllBytes(f.Path);var s=f.Service.Load(f.Path,f.Root,version);var service=new BackupRestoreService(f.Root+"-transactions");var tx=service.ExecuteAsync(f.Root,[f.Service.PrepareTransaction(s,Values(mode),()=>true)]).GetAwaiter().GetResult();var after=f.Service.Load(f.Path,f.Root,version);Check(Values(mode).All(p=>after.Settings.Single(x=>x.Definition.Key==p.Key).EffectiveValue==p.Value),"INI method mismatch");Check(after.Settings.Single(x=>x.Definition.Key=="ForceBorderless").EffectiveValue=="1"&&after.Settings.Single(x=>x.Definition.Key=="UIStabilization").EffectiveValue=="1","Independent setting reset");Check(File.ReadAllText(f.Path).Contains("[Foreign]\r\nKeep=yes\r\n"),"Unknown section lost");service.RestoreAsync(f.Root,tx.TransactionId).GetAwaiter().GetResult();Check(File.ReadAllBytes(f.Path).SequenceEqual(before),"Restore did not preserve exact original bytes");}}
    private static void Lockout(){var f=Fixture();File.WriteAllText(f.Path,"[Backend]\nSelected=DLSSG\n[DLSSG]\nXmxGenerator=1\n");var path=Path.Combine(f.Root,"ReShade.ini");File.WriteAllText(path,"[RenoDX.MFGUnlock]\nTemporalFix=1\n");var service=new MfgUnlockSettingsService();foreach(var version in new[]{"1.8.0.0","1.8.1","1,8,1,0"}){var s=service.Load(path,f.Root,version);Reject(()=>service.CreateUpdatedBytes(s,new Dictionary<string,string>{{"TemporalFix","0"}}));}Check(File.ReadAllText(path).Contains("TemporalFix=1"),"Blocked setting changed");}
    private static void Guards(){var f=Fixture();File.WriteAllText(f.Path,"[Backend]\nSelected=DLSSG\n");var s=f.Service.Load(f.Path,f.Root,"1.8.1");Reject(()=>f.Service.PrepareTransaction(s,Values("XMX"),()=>false));Reject(()=>f.Service.CreateUpdatedBytes(s,new Dictionary<string,string>{{"Selected","bogus"}}));File.AppendAllText(f.Path,"; external\n");Reject(()=>f.Service.CreateUpdatedBytes(s,Values("XMX")));Check(!File.ReadAllText(f.Path).Contains("XmxGenerator"),"Blocked operation wrote config");}
    private static void Intel(){foreach(var version in new[]{"1.8.0.0","1.8.1","1.8.1.0"})Check(IntelRuntimeService.SupportsIntegration(version,IntelIntegration.D3D12)&&IntelRuntimeService.SupportsIntegration(version,IntelIntegration.VulkanExperimental),"Reviewed Intel gate missing");Check(!IntelRuntimeService.SupportsAddon("1.5.7")&&!IntelRuntimeService.SupportsIntegration("1.8.1",(IntelIntegration)9),"Unknown integration enabled");Check(IntelRuntimeService.Assets.Single(a=>a.Name=="libxess_fg.dll").Sha256=="ec5e0c65e075570c6ede72618bb666d0be0c2e10b2ea9762c0fe8cb8e375ab27"&&IntelRuntimeService.Assets.Single(a=>a.Name=="libxell.dll").Sha256=="d2030dcd694fda8f2ec7e044b13e6db8f0b56d4ba9113a5efad334e3f3ded8c7","Pinned dependencies changed");}
    private static void Diagnostics(){var f=Fixture();File.WriteAllText(f.Path,"[Backend]\nSelected=DLSSG\n[DLSSG]\nXmxGenerator=1\n");var report=RuntimeDiagnosticsService.ConfigurationEvidence(f.Service.Load(f.Path,f.Root,"1.8.1"));Check(report.Contains("XMX (experimental)")&&report.Contains("not verified"),"Saved config falsely treated as active or rejected");}
    private static void Messages(){var root=Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"../../../../.."));var code=File.ReadAllText(Path.Combine(root,"RenoDXMfgUnlocker","MainWindow.MfgCategories.cs"));Check(code.Contains("language.Lookup(\""+Unavailable+"\")")&&!code.Contains("requires reviewed addon 1.8.0.0"),"Live UI still has obsolete requirement");var l=new UiLocalization();Check(l.ValidateCatalogs().Count==0,"Catalog integrity failed");foreach(var culture in UiLocalization.Cultures){Check(l.GetCatalog(culture).ContainsKey(Unavailable),"Missing localized reason: "+culture);Check(l.Lookup(Unavailable,culture).Contains("1.8.0"),"Obsolete version-specific reason");}}
}
